// Form f = new Form();   // Fehler! Von abstrakten Klassen gibt es keine Objekte

Rechteck r = new Rechteck(4, 5);
r.Beschreiben();
// Ausgabe: Rechteck mit Fläche 20

abstract class Form
{
    public string Name { get; }

    public Form(string name)
    {
        Name = name;
    }

    // abstrakte Methode: kein Methodenkörper, nur ein ;
    public abstract int Flaeche();

    // normale Methode, die alle Formen erben
    public void Beschreiben()
    {
        Console.WriteLine($"{Name} mit Fläche {Flaeche()}");
    }
}

class Rechteck : Form
{
    private int breite;
    private int hoehe;

    public Rechteck(int breite, int hoehe) : base("Rechteck")
    {
        this.breite = breite;
        this.hoehe = hoehe;
    }

    public override int Flaeche()
    {
        return breite * hoehe;
    }
}

Form[] formen = { new Quadrat(3), new Dreieck(4, 6), new Quadrat(5) };

int summe = 0;
foreach (Form f in formen)
{
    Console.WriteLine($"{f.Name}: {f.Flaeche()}");
    summe += f.Flaeche();
}
Console.WriteLine($"Gesamt: {summe}");
// Ausgabe:
// Quadrat: 9
// Dreieck: 12
// Quadrat: 25
// Gesamt: 46

abstract class Form
{
    public abstract string Name { get; }
    public abstract int Flaeche();
}

class Quadrat : Form
{
    private int seite;
    public Quadrat(int seite) { this.seite = seite; }

    public override string Name => "Quadrat";
    public override int Flaeche() => seite * seite;
}

class Dreieck : Form
{
    private int grundlinie;
    private int hoehe;
    public Dreieck(int g, int h) { grundlinie = g; hoehe = h; }

    public override string Name => "Dreieck";
    public override int Flaeche() => grundlinie * hoehe / 2;
}

// So sieht der Fehler aus, wenn eine abstrakte Methode fehlt:
