abstract class Tier
{
    public abstract void Laut();
}

class Katze : Tier
{
    public override void Laut()
    {
        Console.WriteLine("Miau");
    }
}

Fahrzeug f = new Fahrrad();
f.Info();

abstract class Fahrzeug
{
    public abstract string Typ();
    public abstract int MaxTempo();

    public void Info()
    {
        Console.WriteLine($"{Typ()} fährt mit {MaxTempo()} km/h");
    }
}

class Fahrrad : Fahrzeug
{
    public override string Typ() => "Fahrrad";
    public override int MaxTempo() => 25;
}

Medaille[] liste = { new Gold(), new Silber() };
int summe = 0;
foreach (Medaille m in liste)
{
    summe += m.Punkte();
}
Console.WriteLine(summe);

abstract class Medaille
{
    public abstract int Punkte();
}

class Gold : Medaille
{
    public override int Punkte() => 5 + 3;
}

class Silber : Medaille
{
    public override int Punkte() => 3;
}
